# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: emit
def emit(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: render
def render(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(render(emit(sift(raw))))

